import net from 'net';
import { EventEmitter } from 'events';

interface ProxyConfig {
  listenPort: number;
  targetHost: string;
  targetPort: number;
  logFormat: string;
}

class LogFormatter {
  private template: string;
  private substitutions: Map<string, () => string>;

  constructor(template: string) {
    this.template = template;
    this.substitutions = new Map();
  }

  registerSubstitution(key: string, resolver: () => string): void {
    this.substitutions.set(key, resolver);
  }

  format(dynamicContext: Record<string, string>): string {
    let result = this.template;
    for (const [key, resolver] of this.substitutions.entries()) {
      result = result.replace(new RegExp(`%${key}`, 'g'), resolver());
    }
    // Apply dynamic context substitutions
    for (const [key, value] of Object.entries(dynamicContext)) {
      result = result.replace(new RegExp(`%${key}`, 'g'), value);
    }
    return result;
  }
}

class ConnectionTracker extends EventEmitter {
  private connections: Map<string, { startTime: number; bytesIn: number; bytesOut: number }>;

  constructor() {
    super();
    this.connections = new Map();
  }

  track(id: string): void {
    this.connections.set(id, { startTime: Date.now(), bytesIn: 0, bytesOut: 0 });
  }

  updateBytes(id: string, direction: 'in' | 'out', bytes: number): void {
    const conn = this.connections.get(id);
    if (conn) {
      if (direction === 'in') conn.bytesIn += bytes;
      else conn.bytesOut += bytes;
    }
  }

  getSummary(id: string): string {
    const conn = this.connections.get(id);
    if (!conn) return 'unknown';
    return `in=${conn.bytesIn},out=${conn.bytesOut},dur=${Date.now() - conn.startTime}ms`;
  }

  remove(id: string): void {
    this.connections.delete(id);
  }
}

class AsyncProxyServer {
  private config: ProxyConfig;
  private server: net.Server;
  private tracker: ConnectionTracker;
  private formatter: LogFormatter;
  private connCounter: number = 0;

  constructor(config: ProxyConfig) {
    this.config = config;
    this.tracker = new ConnectionTracker();
    this.formatter = new LogFormatter(config.logFormat);
    this.server = net.createServer((socket) => this.handleConnection(socket));

    this.formatter.registerSubstitution('timestamp', () => new Date().toISOString());
    this.formatter.registerSubstitution('pid', () => process.pid.toString());
  }

  private generateConnId(): string {
    return `conn_${++this.connCounter}_${Date.now()}`;
  }

  private async resolveTarget(): Promise<{ host: string; port: number }> {
    return { host: this.config.targetHost, port: this.config.targetPort };
  }

  private async handleConnection(clientSocket: net.Socket): Promise<void> {
    const connId = this.generateConnId();
    const clientAddr = `${clientSocket.remoteAddress}:${clientSocket.remotePort}`;
    this.tracker.track(connId);

    const target = await this.resolveTarget();
    const targetSocket = net.createConnection(target.port, target.host);

    const logEvent = (event: string, detail: string) => {
      const context: Record<string, string> = {
        connId: connId,
        clientAddr: clientAddr,
        event: event,
        detail: detail,
        summary: this.tracker.getSummary(connId)
      };
      const message = this.formatter.format(context);
      this.emitLog(message);
    };

    logEvent('connect', `new connection from ${clientAddr}`);

    targetSocket.on('connect', () => {
      logEvent('upstream_connect', `connected to ${target.host}:${target.port}`);
    });

    clientSocket.on('data', (data: Buffer) => {
      this.tracker.updateBytes(connId, 'in', data.length);
      const preview = data.slice(0, 64).toString('utf-8').replace(/[\r\n]/g, ' ');
      logEvent('client_data', preview);
      targetSocket.write(data);
    });

    targetSocket.on('data', (data: Buffer) => {
      this.tracker.updateBytes(connId, 'out', data.length);
      const preview = data.slice(0, 64).toString('utf-8').replace(/[\r\n]/g, ' ');
      logEvent('server_data', preview);
      clientSocket.write(data);
    });

    const cleanup = (source: string) => {
      logEvent('disconnect', `${source} closed, ${this.tracker.getSummary(connId)}`);
      this.tracker.remove(connId);
      clientSocket.destroy();
      targetSocket.destroy();
    };

    clientSocket.on('close', () => cleanup('client'));
    targetSocket.on('close', () => cleanup('target'));
    clientSocket.on('error', (err) => logEvent('error', err.message));
    targetSocket.on('error', (err) => logEvent('error', err.message));
  }

  private emitLog(message: string): void {
    // Direct string output - no format string interpretation
    process.stdout.write(message + '\n');
  }

  async start(): Promise<void> {
    return new Promise((resolve) => {
      this.server.listen(this.config.listenPort, () => {
        const msg = this.formatter.format({
          event: 'start',
          detail: `Proxy listening on port ${this.config.listenPort}`,
          connId: 'system',
          clientAddr: 'N/A',
          summary: 'N/A'
        });
        this.emitLog(msg);
        resolve();
      });
    });
  }
}

const config: ProxyConfig = {
  listenPort: parseInt(process.env.PROXY_PORT || '8080'),
  targetHost: process.env.TARGET_HOST || '127.0.0.1',
  targetPort: parseInt(process.env.TARGET_PORT || '3000'),
  logFormat: process.env.LOG_FORMAT || '[%timestamp] [%pid] %event: %detail (%connId, %summary)'
};

const proxy = new AsyncProxyServer(config);
proxy.start().catch(console.error);
